command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="049626c146b158520f82d692d6a44a97c381fc85"
$candidate="c229e1c0de072f2724c42094430524cd2b78c4f2"
$branch="work/removable-transfer-20261006"
$temp=Join-Path $env:RUNNER_TEMP ("fly-removable-transfer-"+$env:GITHUB_RUN_ID)
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "removable transfer fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before removable transfer acceptance"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "removable transfer candidate moved"}
if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp 2>$null; Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue}
& git worktree add --detach $temp $candidate
if($LASTEXITCODE -ne 0){throw "removable transfer worktree creation failed"}
try{
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "removable transfer diff check failed"}

  & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
  if($LASTEXITCODE -ne 0){throw "removable transfer FAST failed"}

  & cmd /c tests\winui\m22\build.cmd Release
  if($LASTEXITCODE -ne 0){throw "M22 Release fixture build failed"}
  $env:FLY_M22_CONFIG="Release"
  & python -X utf8 tests\winui\m22\test_native.py
  if($LASTEXITCODE -ne 0){throw "M22 Release native acceptance failed"}
  Remove-Item Env:\FLY_M22_CONFIG -ErrorAction SilentlyContinue

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "canonical Release build failed"}

  & python -X utf8 tools\winui\run_checks.py gui --area file-operations --configuration Release
  if($LASTEXITCODE -ne 0){throw "file-operations GUI regression failed"}

  Write-Host "REMOVABLE_TRANSFER_FAST=PASS"
  Write-Host "REMOVABLE_TRANSFER_M22_NATIVE=PASS"
  Write-Host "REMOVABLE_TRANSFER_RELEASE=PASS"
  Write-Host "REMOVABLE_TRANSFER_GUI_FIXED_REGRESSION=PASS"
  Write-Host "REMOVABLE_TRANSFER_PHYSICAL_USB=NOT_RUN_NO_DEVICE"
} finally {
  Set-Location -LiteralPath $repo
  Remove-Item Env:\FLY_M22_CONFIG -ErrorAction SilentlyContinue
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
